using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class B5WayfindingProbePlan {
 static Transform root;static Vector3 V(JToken t)=>new Vector3((float)t[0],-82,(float)t[1]);
 static object Check(Vector3 p,float radius){var hits=Physics.RaycastAll(p+Vector3.up*.30f,Vector3.down,.65f,~0,QueryTriggerInteraction.Ignore);bool ground=hits.Any(h=>h.normal.y>.8f&&h.collider.transform.IsChildOf(root));var blocks=Physics.OverlapCapsule(p+Vector3.up*.36f,p+Vector3.up*1.5f,radius,~0,QueryTriggerInteraction.Ignore).Where(c=>c.enabled&&c.transform.IsChildOf(root)&&!c.name.Contains("Floor")&&!c.name.Contains("Threshold")).Select(c=>c.name).Distinct().ToArray();return !ground||blocks.Length>0?new{position=new[]{p.x,p.z},ground,blocks}:null;}
 public static object Run(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||!s.path.EndsWith("Level_B5_Circular.unity"))throw new Exception("B5 edit scene required");bool dirty=s.isDirty;root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;string repo=Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));string output=repo+"/Docs/도면/Decision/원형공동/B5_안내체계/";var plan=JObject.Parse(File.ReadAllText(output+"wayfinding_plan.json"));Physics.SyncTransforms();int pathSamples=0,labelSamples=0;var badPaths=new List<object>();var badLabels=new List<object>();foreach(var path in plan["paths"]){var p=path["points"].Select(V).ToArray();for(int i=1;i<p.Length;i++){int n=Mathf.Max(1,Mathf.CeilToInt(Vector3.Distance(p[i-1],p[i])/.15f));for(int j=0;j<=n;j++){pathSamples++;var bad=Check(Vector3.Lerp(p[i-1],p[i],(float)j/n),.22f);if(bad!=null)badPaths.Add(new{id=(string)path["id"],bad});}}}foreach(var l in plan["labels"]){var center=V(l["position"]);var forward=V(l["forward"]);forward.y=0;var right=Vector3.Cross(Vector3.up,forward);for(int i=-2;i<=2;i++)for(int j=-3;j<=3;j++){labelSamples++;var p=center+right*(float)l["width"]*i/4+forward*(float)l["length"]*j/6;var bad=Check(p,.035f);if(bad!=null)badLabels.Add(new{id=(string)l["id"],bad});}}var result=new{pathSamples,labelSamples,badPaths,badLabels,dirtyBefore=dirty,dirtyAfter=s.isDirty,scope="Read-only candidate geometry probe. This does not instantiate floor paint or verify rendered text."};File.WriteAllText(output+"unity_probe.json",JsonConvert.SerializeObject(result,Formatting.Indented));return new{pathSamples,labelSamples,pathProblems=badPaths.Count,labelProblems=badLabels.Count,dirtyBefore=dirty,dirtyAfter=s.isDirty};}
}
